"""nodup_imports.py -- lint Python files for duplicate and unused imports.

Usage:
    python nodup_imports.py FILE [FILE ...]

Findings are reported one per line as:

    path:lineno: CODE message

Codes:
    NDI001  duplicate import of the same module
    NDI002  import that is never used in the file

Exit status is 1 if any finding was reported, 0 otherwise.
"""

from __future__ import annotations

import argparse
import ast
import sys

NDI001 = "NDI001"  # duplicate import of the same module
NDI002 = "NDI002"  # unused import


class _Collector(ast.NodeVisitor):
    """Collects imported bindings, duplicate imports, and used names."""

    def __init__(self) -> None:
        #: module name -> first import lineno (plain ``import x[.y]``)
        self.plain_seen: dict[str, int] = {}
        #: (module, name) -> first import lineno (``from m import n``)
        self.from_seen: dict[tuple[str, str], int] = {}
        #: binding name -> (lineno, code, message) for candidate NDI002s
        self.imported_names: dict[str, tuple[int, str, str]] = {}
        #: every name read anywhere in the module (roots of attribute chains)
        self.used_names: set[str] = set()
        self.findings: list[tuple[int, str, str]] = []

    # -- import statements -------------------------------------------------

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            if alias.name == "__future__":
                continue  # compiler directive, not a real binding
            if alias.name in self.plain_seen:
                self.findings.append(
                    (
                        node.lineno,
                        NDI001,
                        f"duplicate import of module '{alias.name}'",
                    )
                )
            else:
                self.plain_seen[alias.name] = node.lineno
            bound = alias.asname or alias.name.split(".")[0]
            what = alias.asname or alias.name
            self._track(bound, node.lineno, f"'{what}' is imported but never used")

    def visit_From(self, node: ast.ImportFrom) -> None:  # pragma: no cover
        raise NotImplementedError  # replaced by generic_visit dispatch below

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        if node.module == "__future__":
            return
        module = node.module or ""
        for alias in node.names:
            if alias.name == "*":
                continue  # cannot track star imports reliably
            key = (module, alias.name)
            if key in self.from_seen:
                self.findings.append(
                    (
                        node.lineno,
                        NDI001,
                        f"duplicate import of '{alias.name}' from module "
                        f"'{module}'",
                    )
                )
            else:
                self.from_seen[key] = node.lineno
            bound = alias.asname or alias.name
            what = alias.asname or alias.name
            self._track(bound, node.lineno, f"'{what}' is imported but never used")

    def _track(self, bound: str, lineno: int, message: str) -> None:
        if bound in self.imported_names:
            # Rebinding the same name: only the last binding can be live;
            # report the earlier one as an unused shadowed import unless it
            # was used before being rebound. Simplest sound choice: keep the
            # latest binding as the candidate.
            old = self.imported_names[bound]
            self.findings.append((old[1], old[2], old[3]))
        self.imported_names[bound] = (bound, lineno, NDI002, message)

    # -- name usage --------------------------------------------------------

    def visit_Name(self, node: ast.Name) -> None:
        self.used_names.add(node.id)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        # Walking to the root Name covers chains like os.path.join -> 'os'.
        self.generic_visit(node)


def analyze_source(source: str) -> list[tuple[int, str, str]]:
    """Return sorted (lineno, code, message) findings for a source string."""
    tree = ast.parse(source)
    collector = _Collector()
    collector.visit(tree)

    for name, (_, lineno, code, message) in collector.imported_names.items():
        if name not in collector.used_names:
            collector.findings.append((lineno, code, message))

    return sorted(collector.findings, key=lambda f: (f[0], f[1], f[2]))


def check_file(path: str) -> list[tuple[str, int, str, str]]:
    """Lint one file; return findings as (path, lineno, code, message)."""
    with open(path, encoding="utf-8") as fh:
        source = fh.read()
    return [(path, lineno, code, msg) for lineno, code, msg in analyze_source(source)]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Report duplicate (NDI001) and unused (NDI002) imports."
    )
    parser.add_argument("files", nargs="+", help="Python files to check")
    args = parser.parse_args(argv)

    findings: list[tuple[str, int, str, str]] = []
    for path in args.files:
        try:
            findings.extend(check_file(path))
        except SyntaxError as exc:
            print(f"{path}:0: NDIE00 syntax error: {exc.msg}", file=sys.stderr)
            return 2

    for path, lineno, code, message in findings:
        print(f"{path}:{lineno}: {code} {message}")
    return 1 if findings else 0


if __name__ == "__main__":  # pragma: no cover
    sys.exit(main())
"})
